import{_ as e,o as a,c as o,a3 as d}from"./chunks/framework.DNWyyI0w.js";const u=JSON.parse('{"title":"Run Tools Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/run-tools.md","filePath":"reference/run-tools.md"}'),s={name:"reference/run-tools.md"};function n(r,t,i,c,l,h){return a(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="run-tools-reference" tabindex="-1">Run Tools Reference <a class="header-anchor" href="#run-tools-reference" aria-label="Permalink to &quot;Run Tools Reference&quot;">​</a></h1><p>Every Run gives PRIME a small, fixed toolbelt. These nine tools are the <em>only</em> way PRIME can change a Run: set its contract, dispatch work, ship a branch, raise an event, or close it out. They are exposed as an in-process MCP server named <code>saidi_run</code>, so their fully-qualified names are <code>mcp__saidi_run__&lt;tool&gt;</code>.</p><p>The toolbelt below is the canonical list.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Mutates the Run?</th></tr></thead><tbody><tr><td><a href="#set-plan"><code>set_plan</code></a></td><td>Freeze the Run&#39;s task contract</td><td>Yes — once</td></tr><tr><td><a href="#amend-plan"><code>amend_plan</code></a></td><td>Change the frozen plan, with a reason</td><td>Yes</td></tr><tr><td><a href="#delegate"><code>delegate</code></a></td><td>Hand one task to one agent</td><td>Yes</td></tr><tr><td><a href="#delegate-batch"><code>delegate_batch</code></a></td><td>Run 2–8 independent tasks concurrently</td><td>Yes</td></tr><tr><td><a href="#get-run-state"><code>get_run_state</code></a></td><td>Read the durable plan back</td><td>No — read-only</td></tr><tr><td><a href="#publish"><code>publish</code></a></td><td>Push a project&#39;s run branch and open a PR</td><td>Yes — remote</td></tr><tr><td><a href="#raise-event"><code>raise_event</code></a></td><td>Emit an event onto the reflex bus</td><td>Yes — may start other Runs</td></tr><tr><td><a href="#attach-assets"><code>attach_assets</code></a></td><td>Attach generated files into the Run chat</td><td>Yes — chat only</td></tr><tr><td><a href="#finish-run"><code>finish_run</code></a></td><td>Close the Run once its objective is met</td><td>Yes — terminal</td></tr></tbody></table><p>A recurring theme runs through all of them: <strong>the tools refuse rather than comply</strong> when the Run&#39;s contract would be violated. A refusal comes back as an MCP error result with an explanation, and PRIME has to deal with it. See <a href="/docs/concepts/verification">Verification &amp; Evidence</a> for why the gates exist.</p><h2 id="planning-tools" tabindex="-1">Planning tools <a class="header-anchor" href="#planning-tools" aria-label="Permalink to &quot;Planning tools&quot;">​</a></h2><h3 id="set-plan" tabindex="-1">set_plan <a class="header-anchor" href="#set-plan" aria-label="Permalink to &quot;set_plan&quot;">​</a></h3><p>Sets the Run&#39;s task plan. PRIME calls this <strong>once</strong>, on its first turn, before delegating anything. The plan becomes the Run&#39;s contract — what the Run is measured against and what <code>finish_run</code> later checks.</p><p><strong>Parameters</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>items</code></td><td><code>PlanItem[]</code></td><td>Yes</td><td>The full task list, in order. Minimum 1, maximum 12.</td></tr></tbody></table><p><strong>The <code>PlanItem</code> shape</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td>Optional</td><td>Short stable id, e.g. <code>&quot;api&quot;</code>, <code>&quot;ui&quot;</code>, <code>&quot;verify&quot;</code>. Preserved across amendments. Generated if omitted.</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>Yes</td><td>One concrete step, short.</td></tr><tr><td><code>assignee</code></td><td><code>string</code></td><td>Optional</td><td>Agent or project responsible for this task.</td></tr><tr><td><code>dependsOn</code></td><td><code>string[]</code></td><td>Optional</td><td>Task ids that must be <code>done</code> first.</td></tr><tr><td><code>mode</code></td><td><code>&quot;ask&quot; | &quot;work&quot;</code></td><td>Optional</td><td>Read-only Q&amp;A vs. change-making.</td></tr><tr><td><code>effort</code></td><td><code>&quot;low&quot; | &quot;medium&quot; | &quot;high&quot;</code></td><td>Optional</td><td>Reasoning tier. <code>low</code> for simple read-only lookups, <code>medium</code> for normal audit/build/verification work, <code>high</code> only for unusually hard judgment or design.</td></tr><tr><td><code>attemptBudget</code></td><td><code>integer ≥ 1</code></td><td>Optional</td><td>Retries this task may use before the Run escalates. Clamped to the configured maximum — <strong>a plan cannot raise its own ceiling</strong>.</td></tr><tr><td><code>acceptanceCriteria</code></td><td><code>string[]</code></td><td><strong>Yes</strong></td><td>1–5 observable conditions for completion.</td></tr><tr><td><code>checks</code></td><td><code>Check[]</code></td><td>Optional</td><td>Mechanical assertions. Max <code>MAX_TASK_CHECKS</code>.</td></tr><tr><td><code>proofs</code></td><td><code>Proof[]</code></td><td>Optional</td><td>Deterministic evidence. Max 5.</td></tr></tbody></table><p><strong><code>acceptanceCriteria</code> is mandatory and is enforced.</strong> Each entry must be something a checker can rule on: a file that must exist, a command that must pass, a count, an output that must contain a specific thing. <code>&quot;it looks good&quot;</code> is rejected. Criteria should be scoped to the symptom in the brief, not an exhaustive survey of the surrounding subsystem.</p><p><strong>The <code>Check</code> shape</strong> — one mechanical assertion each, judged <strong>only</strong> by exit code.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>cmd</code></td><td><code>string</code></td><td>Shell command, capped at <code>MAX_CHECK_CMD_CHARS</code>.</td></tr><tr><td><code>expectExit</code></td><td><code>integer</code></td><td>Exit code that means passed. Default <code>0</code>.</td></tr><tr><td><code>criterion</code></td><td><code>string</code></td><td>Which acceptance criterion this proves — set it to the criterion&#39;s exact text.</td></tr></tbody></table><p>Checks are deliberately weak-by-design in one direction and strong in the other: a <strong>failing</strong> check fails the task outright, but a <strong>passing</strong> check does <em>not</em> complete it. PRIME wrote both the criteria and the checks, so the verifier still rules on every criterion independently. Checks make the gate stricter, never weaker. They may only run inspection commands — <code>test</code>, <code>grep</code>, <code>npm</code>/<code>npx</code>, read-only <code>git</code> — with no writes, no network, and no <code>node -e</code>. The assigned agent is shown them in its brief.</p><p><strong>The <code>Proof</code> shape</strong> — closed-vocabulary deterministic evidence, preferred over asking a worker to paste files or raw build logs inline.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>criterion</code></td><td><code>string</code></td><td>Exact acceptance-criterion text this proves.</td></tr><tr><td><code>kind</code></td><td><code>&quot;fileExists&quot; | &quot;assetCount&quot;</code></td><td>The proof type.</td></tr><tr><td><code>path</code></td><td><code>string</code></td><td>Safe relative path, for <code>fileExists</code>.</td></tr><tr><td><code>minCount</code></td><td><code>integer ≥ 1</code></td><td>Minimum matching run assets, for <code>assetCount</code>.</td></tr><tr><td><code>extension</code></td><td><code>string</code></td><td>Optional extension filter such as <code>.png</code>.</td></tr></tbody></table><p><strong>Refusals</strong></p><ul><li>Calling <code>set_plan</code> when a plan already exists returns an error directing PRIME to <code>amend_plan</code> instead — silently replacing the plan &quot;is how a run ends up somewhere different every time it is run&quot;.</li><li>A plan failing validation returns <code>Plan rejected:</code> followed by the specific problems.</li></ul><p><strong>On success</strong> the plan is normalized, stored, and frozen. If the Run requires plan approval, the plan is <em>not</em> dispatched: its approval state is set to <code>pending</code>, a question event is posted to the operator listing each task with its criteria, and PRIME is told to stop and wait. This is the checkpoint for <em>&quot;is this the right work&quot;</em> — distinct from verification, which answers the later question <em>&quot;was it actually done&quot;</em>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Plan set and frozen (5 tasks). It is now this run&#39;s contract — change it only with</span></span>
<span class="line"><span>amend_plan, stating why.</span></span></code></pre></div><h3 id="amend-plan" tabindex="-1">amend_plan <a class="header-anchor" href="#amend-plan" aria-label="Permalink to &quot;amend_plan&quot;">​</a></h3><p>Changes a frozen plan, on the record. Every amendment appends a system event noting the reason and the drift since the original plan — how many tasks were added, removed, and reworded.</p><p><strong>Parameters</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>reason</code></td><td><code>string</code></td><td>Yes</td><td>Minimum 8 characters. Why the plan must change — what reality turned out to be different.</td></tr><tr><td><code>items</code></td><td><code>PlanItem[]</code></td><td>Yes</td><td>The <strong>full</strong> revised task list, in order, 1–12 items. Same shape as <code>set_plan</code>.</td></tr></tbody></table><p>Pass the entire list every time and preserve existing ids.</p><p><strong>What an amendment may not do</strong></p><ul><li>It cannot drop or reopen a task that is already <code>done</code>.</li><li>It cannot remove a task&#39;s acceptance criteria.</li><li>It cannot set task status. <strong>Status belongs to the engine</strong> — an amendment cannot mark work done.</li><li>It cannot be called before a plan exists; you get <code>There is no plan to amend yet — call set_plan first.</code></li></ul><p>Legitimate reasons are narrow: the work turned out to need a step nobody knew about, or a step turned out not to apply. Because every amendment is recorded, the incentive is to get the plan right in <code>set_plan</code>.</p><p>A rejected amendment returns <code>Amendment rejected:</code> with the specific problems. A successful one returns the new plan version and task count.</p><h3 id="get-run-state" tabindex="-1">get_run_state <a class="header-anchor" href="#get-run-state" aria-label="Permalink to &quot;get_run_state&quot;">​</a></h3><p>Reads the Run&#39;s durable plan back from the store. <strong>Read-only, so it is always safe to call.</strong></p><p><strong>Parameters</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>taskIds</code></td><td><code>string[]</code></td><td>Optional</td><td>Only these task ids. Omit for the whole plan.</td></tr><tr><td><code>includeEvidence</code></td><td><code>boolean</code></td><td>Optional</td><td>Include each task&#39;s latest evidence. Default <code>true</code>.</td></tr></tbody></table><p>Each Run turn already carries a live-state block listing every open task, which covers the normal case. <code>get_run_state</code> exists for the two cases it cannot cover:</p><ol><li>A plan longer than the live-state block displays.</li><li>A PRIME whose session was just compacted and needs the criteria and evidence behind a task — not just its status.</li></ol><p><strong>Returns</strong> a plan version header with a done/total count, then one block per task containing id, status, assignee, attempt number, task text, acceptance criteria, the verification verdict (status, who ruled, and reason), and the latest evidence clipped to 1,200 characters.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Plan v2 — 3/5 done.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### api — done · corex · attempt 1</span></span>
<span class="line"><span>Add the /health endpoint</span></span>
<span class="line"><span>Criteria:</span></span>
<span class="line"><span>- GET /health returns 200</span></span>
<span class="line"><span>Verdict: pass (by verifier)</span></span>
<span class="line"><span>Evidence: curl -s -o /dev/null -w &quot;%{http_code}&quot; … → 200</span></span></code></pre></div><p>Errors if the Run no longer exists, if no task matches the supplied ids, or if the Run has no plan yet.</p><h2 id="delegation-tools" tabindex="-1">Delegation tools <a class="header-anchor" href="#delegation-tools" aria-label="Permalink to &quot;Delegation tools&quot;">​</a></h2><h3 id="delegate" tabindex="-1">delegate <a class="header-anchor" href="#delegate" aria-label="Permalink to &quot;delegate&quot;">​</a></h3><p>Hands <strong>one</strong> piece of the Run to a project or department agent. The agent streams live into the Run thread and its task status updates automatically.</p><p><strong>Parameters</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>target</code></td><td><code>string</code></td><td>Yes</td><td>Project registry name or custom agent name.</td></tr><tr><td><code>task</code></td><td><code>string</code></td><td>Yes</td><td>Precisely what the agent should do or answer.</td></tr><tr><td><code>mode</code></td><td><code>&quot;ask&quot; | &quot;work&quot;</code></td><td>Optional</td><td><code>ask</code> is read-only repo Q&amp;A; <code>work</code> may run commands or make a change on the run branch.</td></tr><tr><td><code>taskId</code></td><td><code>string</code></td><td>Optional</td><td>Stable id of the matching <code>set_plan</code> item — this is what links the delegation to the checklist.</td></tr><tr><td><code>approved</code></td><td><code>boolean</code></td><td>Optional</td><td>Set true <strong>only</strong> after the owner explicitly approved this exact change.</td></tr></tbody></table><p><code>approved</code> is the approval-gate carrier. It is not a convenience flag: it asserts that a human signed off on this specific change, and project policy decides whether that assertion is required. See <a href="/docs/reference/project-policy">Project Policy</a> and <a href="/docs/guides/guardrails">Approval &amp; Spend Guardrails</a>.</p><p>Always pass <code>taskId</code>. Without it the delegation is orphaned from the plan, and nothing updates the checklist item it was meant to satisfy.</p><h3 id="delegate-batch" tabindex="-1">delegate_batch <a class="header-anchor" href="#delegate-batch" aria-label="Permalink to &quot;delegate_batch&quot;">​</a></h3><p>Runs 2–8 <strong>independent</strong>, ready checklist tasks concurrently.</p><p><strong>Parameters</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>tasks</code></td><td><code>object[]</code></td><td>Yes</td><td>Minimum 2, maximum 8 items.</td></tr><tr><td><code>tasks[].target</code></td><td><code>string</code></td><td>Yes</td><td>Project registry name or custom agent name.</td></tr><tr><td><code>tasks[].task</code></td><td><code>string</code></td><td>Yes</td><td>Precisely what this agent should do or answer.</td></tr><tr><td><code>tasks[].mode</code></td><td><code>&quot;ask&quot; | &quot;work&quot;</code></td><td>Optional</td><td><code>ask</code> for read-only repo Q&amp;A, <code>work</code> otherwise.</td></tr><tr><td><code>tasks[].taskId</code></td><td><code>string</code></td><td><strong>Yes</strong></td><td>Required here, unlike in <code>delegate</code>.</td></tr></tbody></table><p>Note the one schema difference from <code>delegate</code>: <code>taskId</code> is <strong>required</strong> for every batch item, and there is no <code>approved</code> field — approval-gated work cannot be batched at all.</p><p><strong>The five preconditions, each with its own refusal</strong></p><table tabindex="0"><thead><tr><th>Condition</th><th>Refusal</th></tr></thead><tbody><tr><td>Duplicate <code>taskId</code>s in the batch</td><td><code>delegate_batch requires a distinct taskId for every item.</code></td></tr><tr><td>A <code>taskId</code> not present in the plan</td><td><code>Unknown checklist taskId(s): …. They must exist in the plan.</code></td></tr><tr><td>A task whose <code>dependsOn</code> entries are not yet done</td><td><code>Not batching: dependencies are still open for ….</code></td></tr><tr><td>Two items resolving to the same canonical agent/project</td><td><code>delegate_batch requires distinct agents/projects. Work aimed at the same target must be sequenced with delegate.</code></td></tr><tr><td>A <code>work</code>-mode project task whose policy approval is <code>confirm</code></td><td><code>Approval-gated work cannot start in a batch: …. Delegate those tasks individually.</code></td></tr></tbody></table><p>Targets are resolved to their canonical registry names <em>before</em> the duplicate check, so two different aliases for the same project are still caught.</p><p><strong>Failure isolation.</strong> The batch settles all delegations rather than aborting on the first error. Successful results are preserved when a sibling fails, and each checklist task receives its own final status. The combined result is only marked as an error if <em>every</em> item failed. Results come back as one block per item, headed <code>### &lt;taskId&gt; · &lt;target&gt;</code>.</p><p>The batch also short-circuits before doing anything if the Run was stopped, or if the account&#39;s usage limit is blocking work — see <a href="/docs/concepts/credits-and-usage">Credits, Usage &amp; Spend Limits</a>.</p><h2 id="output-tools" tabindex="-1">Output tools <a class="header-anchor" href="#output-tools" aria-label="Permalink to &quot;Output tools&quot;">​</a></h2><h3 id="publish" tabindex="-1">publish <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;publish&quot;">​</a></h3><p>Publishes a project&#39;s run branch: pushes it to <code>origin</code> and opens a pull request.</p><p><strong>Parameters</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>target</code></td><td><code>string</code></td><td>Yes</td><td>Project registry name whose run branch to publish.</td></tr></tbody></table><p>This tool exists because <strong>run work does not push by itself</strong>. Changes accumulate as local commits on the run branch, and publishing is a deliberate, separate step taken when the owner wants them shipped. See <a href="/docs/concepts/worktrees-and-branches">Worktrees, Branches &amp; Publishing</a>.</p><p>Refuses if the Run was stopped. Otherwise returns whatever the publish attempt reported, flagged as an error if it did not succeed.</p><h3 id="attach-assets" tabindex="-1">attach_assets <a class="header-anchor" href="#attach-assets" aria-label="Permalink to &quot;attach_assets&quot;">​</a></h3><p>Attaches generated files from the Run&#39;s assets folder directly into the Run chat. It does not rerun work and does not modify repo files.</p><p><strong>Parameters</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>files</code></td><td><code>string[]</code></td><td>Optional</td><td>Specific filenames from the Run assets folder. Omit to attach every unattached generated asset.</td></tr><tr><td><code>includeAlreadyAttached</code></td><td><code>boolean</code></td><td>Optional</td><td>Normally false. Set true only if the owner explicitly wants duplicates or a re-send.</td></tr><tr><td><code>note</code></td><td><code>string</code></td><td>Optional</td><td>Short message or caption shown above the attached files.</td></tr></tbody></table><p>Two situations call for it: the owner asks to send or show generated images, screenshots, PDFs, or exports in the chat; or a restart left files in the assets folder without chat attachments.</p><h3 id="raise-event" tabindex="-1">raise_event <a class="header-anchor" href="#raise-event" aria-label="Permalink to &quot;raise_event&quot;">​</a></h3><p>Emits a Saidi event onto the reflex bus from inside the Run.</p><p><strong>Parameters</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>string</code></td><td>Yes</td><td>Event type, e.g. <code>&quot;lead.captured&quot;</code> or <code>&quot;incident.detected&quot;</code>.</td></tr><tr><td><code>payload</code></td><td><code>Record&lt;string, unknown&gt;</code></td><td>Optional</td><td>Normalized fields other reflexes can match on.</td></tr></tbody></table><p>Use it when the Run discovers something actionable that a Reflex should react to — start a run, notify someone, chain further work. A lead was captured; an incident was detected; a threshold was crossed.</p><p>The emitted envelope fixes several fields for you:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><code>source</code></td><td><code>&quot;agent&quot;</code></td></tr><tr><td><code>actor</code></td><td>The Run&#39;s title</td></tr><tr><td><code>runId</code></td><td>The current Run&#39;s id</td></tr><tr><td><code>depth</code></td><td><code>1</code></td></tr><tr><td><code>at</code></td><td>Emission timestamp</td></tr><tr><td><code>id</code></td><td>A fresh event id</td></tr></tbody></table><p><code>depth</code> is the loop guard: events raised from inside a Run are depth-guarded so a reflex that starts a run that raises an event cannot recurse indefinitely. Refuses if the Run was stopped.</p><p>See <a href="/docs/concepts/reflexes-and-events">Reflexes &amp; Events</a> and <a href="/docs/reference/reflex-rules">Reflex Rules</a>.</p><h2 id="finish-run" tabindex="-1">finish_run <a class="header-anchor" href="#finish-run" aria-label="Permalink to &quot;finish_run&quot;">​</a></h2><p>Closes the Run. PRIME calls it when the Run&#39;s objective is fully met.</p><p><strong>Parameters</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>note</code></td><td><code>string</code></td><td>Optional</td><td>One-line outcome summary.</td></tr><tr><td><code>evidence</code></td><td><code>string</code></td><td>Optional</td><td>What was <strong>verified</strong> and how — a build or test that passed, a check an agent ran. Not just what was done.</td></tr></tbody></table><p><strong>Completion is a contract, not a claim.</strong> <code>finish_run</code> applies two independent gates before it will close anything.</p><p><strong>Gate 1 — no open plan steps.</strong> If any task is still open, the tool refuses and lists them:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Not finishing: 2 plan steps are still open:</span></span>
<span class="line"><span>- Add the /health endpoint (in_progress)</span></span>
<span class="line"><span>- Update the deploy doc (pending)</span></span>
<span class="line"><span>Complete them, or amend_plan with a reason if a step genuinely no longer applies (and tell</span></span>
<span class="line"><span>the owner why).</span></span></code></pre></div><p><strong>Gate 2 — nothing &quot;done&quot; that went unverified.</strong> A Run&#39;s <code>executionMode</code> is either <code>guided</code> or <code>autonomous</code>. When verification is active for that mode, any task marked done that nothing actually checked is refused:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Not finishing: 1 step completed without passing verification:</span></span>
<span class="line"><span>- Add the /health endpoint</span></span>
<span class="line"><span>Re-delegate them so their acceptance criteria are actually checked.</span></span></code></pre></div><p>This second gate is the point of the whole design: a task marked done that nothing verified is precisely the claim the layer exists to stop accepting at face value.</p><p>On success the Run is marked complete and, if a note or evidence was supplied, a <code>✔</code> system event is appended to the thread. The owner can still reopen a closed Run.</p><p><code>finish_run</code> is not a way out of a stuck Run. If more work or a decision from the owner remains, PRIME is instructed to say what is left and let the owner steer, rather than closing.</p><h2 id="behaviour-common-to-all-run-tools" tabindex="-1">Behaviour common to all run tools <a class="header-anchor" href="#behaviour-common-to-all-run-tools" aria-label="Permalink to &quot;Behaviour common to all run tools&quot;">​</a></h2><ul><li><strong>Stopped runs.</strong> Tools that dispatch or mutate remote state — <code>delegate</code>, <code>delegate_batch</code>, <code>publish</code>, <code>raise_event</code> — check the abort signal first and return <code>The run was stopped.</code></li><li><strong>Usage blocking.</strong> Delegation paths call the usage gate before dispatching. If the account is blocked, the tool returns the block message instead of starting work.</li><li><strong>Result clipping.</strong> Tool output returned to PRIME is clipped to a cap so a single verbose agent cannot consume the whole context. Batch results share the cap across items with a per-item floor, and clipped content carries a pointer for recovering the detail via the agent.</li><li><strong>Text segmentation.</strong> PRIME&#39;s own prose is segmented by tool call — each contiguous stretch of text between delegations becomes its own message in the thread, which is why the transcript reads as narration interleaved with work rather than one wall of text.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/reference/run-object">The Run Object</a> — the persisted shape these tools read and write</li><li><a href="/docs/concepts/plans-and-tasks">Plans &amp; Tasks</a> — the conceptual model behind <code>set_plan</code></li><li><a href="/docs/concepts/delegation">Delegation</a> — how a delegated task actually executes</li><li><a href="/docs/reference/orchestrator-tools">Orchestrator Tools</a> — the wider toolbelt outside a Run</li></ul>`,94)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
